static int class_field_at48(const Combat*g,int id,float x,float y){for(int i=0;i<3;i++){const ClassArea48*a=&g->classAreas48[i];float r=a->id==104?20+8*((a->rank+1)/2):28;if(a->id==id&&a->until>g->time&&a->map==g->mapId&&fabsf(x-a->x)<=r&&fabsf(y-a->y)<=r){if(id==102){int xx=(int)floorf((x-a->x+28)/8),yy=(int)floorf((y-a->y+28)/8);if(xx<0||xx>=7||yy<0||yy>=7)continue;int cell=yy*7+xx;if(a->waterUsed49[cell/32]&(1u<<(cell%32)))continue;}return a->rank;}}return 0;}
