static void class_magic_tick48(Combat*g){for(int i=0;i<MOB_COUNT;i++){CombatMob*m=&g->mobs[i];if(!m->castUntil48)continue;if(!m->enabled||m->hp<=0||m->stun>0||m->frozenLeft>0||m->stoneLeft>0||m->class50.sleepUntil>g->time||m->class50.silenceUntil>g->time){m->castUntil48=0;continue;}if(m->castUntil48>g->time)continue;int lv=m->castRank48,sp=m->castSP48,sourceSkill=m->castSkill48;m->castUntil48=0;m->castSkill48=m->castRank48=m->castSP48=0;if(g->hp<=0||g->hideLeft>0||!class_ice_line48(g,m->x,m->y,g->x,g->y)||(g->canAim&&!g->canAim(g->world,m->x,m->y,g->x,g->y)))continue;if(class_fog_at52(g,g->x,g->y)&&combat_random(g)%100<75)continue;int raw=lv*20*(100+m->class50.tarotMatk52+(m->class50.mindUntil52>g->time?20*m->class50.mindRank52:0))/100;int guarded=soullinker_magic60(g,i,raw,1);int damage=guarded?class_magic_received48(g,guarded,sp,1):0;damage=item_received_bonus52(g,m,damage,0,1,3);int armor=g->class50.itemElementUntil52>g->time?g->class50.itemElement52:g->itemBonuses52.scalar[B52_bDefEle];if(armor>=0&&armor<10)damage=damage*elementRate48[0][armor][3]/100;if(class_fog_at52(g,g->x,g->y))damage=damage*75/100;if(damage>0&&combat_random(g)%100<(unsigned)g->itemBonuses52.scalar[B52_bMagicDamageReturn]){g->itemProcSkip52=1;skill_hit_now49(g,i,damage,0,1);g->itemProcSkip52=0;damage=0;}class_copy_received50(g,sourceSkill,lv,damage);if(g->debugPlayerInvincible52)damage=0;if(damage>g->hp)damage=g->hp;if(damage>0){g->hp-=damage;item_proc_event52(g,2,i,damage,(unsigned)sourceSkill);g->hurtAt=g->lastDamage=g->time;g->sitting=0;combat_damage_interrupt_cast(g);combat_received_number53(g,damage,lv);if(!g->hp&&!soullinker_revive60(g)){g->deadAt=g->time;g->autoAttack=0;combat_support_clear(g);}}combat_notice(g,POP_DAMAGE,damage?"Practice Fire Bolt: %d magic damage.":"Magic Rod absorbed the practice Fire Bolt.",damage);}}
